python3 -c "
import os, openpyxl, docx, pypdf

def search_xlsx(path):
    wb = openpyxl.load_workbook(path, data_only=True)
    for sheet in wb.sheetnames:
        ws = wb[sheet]
        for row_idx, row in enumerate(ws.iter_rows(values_only=True), 1):
            row_str = ' | '.join([str(c) if c is not None else '' for c in row])
            if 'corwyn' in row_str.lower() or '0629' in row_str.lower() or 'kovalchuk' in row_str.lower() or 'review' in path.lower() or 'contact' in path.lower():
                if 'contact' in path.lower() or 'corwyn' in row_str.lower() or '0629' in row_str.lower():
                    print(f'{path} [{sheet}:R{row_idx}]: {row_str}')

for root, dirs, files in os.walk('/filesystem'):
    for f in sorted(files):
        p = os.path.join(root, f)
        if f.endswith('.xlsx') and not 'PXA-2023-0629' in f:
            try:
                search_xlsx(p)
            except Exception as e:
                print(p, e)
"

