import docx, openpyxl, pypdf

def text_docx(path):
    doc = docx.Document(path)
    out = [f"=== DOCX: {path} ==="]
    for p in doc.paragraphs:
        if p.text.strip(): out.append(p.text)
    for t in doc.tables:
        out.append("--- TABLE ---")
        for row in t.rows:
            out.append(" | ".join(c.text.strip().replace("\n", " ") for c in row.cells))
    return "\n".join(out)

def text_pdf(path):
    reader = pypdf.PdfReader(path)
    out = [f"=== PDF: {path} ==="]
    for i, page in enumerate(reader.pages):
        out.append(f"--- Page {i+1} ---")
        out.append(page.extract_text())
    return "\n".join(out)

def text_xlsx(path):
    wb = openpyxl.load_workbook(path, data_only=True)
    out = [f"=== XLSX: {path} ==="]
    for name in wb.sheetnames:
        out.append(f"--- Sheet: {name} ---")
        ws = wb[name]
        for row in ws.iter_rows(values_only=True):
            if any(v is not None for v in row):
                out.append(" | ".join(str(v) if v is not None else "" for v in row))
    return "\n".join(out)

def dump_list(files, outpath):
    with open(outpath, "w") as fw:
        for f in files:
            if f.endswith(".docx"): fw.write(text_docx(f) + "\n\n")
            elif f.endswith(".pdf"): fw.write(text_pdf(f) + "\n\n")
            elif f.endswith(".xlsx"): fw.write(text_xlsx(f) + "\n\n")

