import os, glob, docx, openpyxl, pypdf

def get_all_text(path):
    try:
        if path.endswith(".docx"):
            doc = docx.Document(path)
            t = "\n".join(p.text for p in doc.paragraphs)
            for tb in doc.tables:
                for r in tb.rows:
                    t += "\n" + " | ".join(c.text for c in r.cells)
            return t
        elif path.endswith(".pdf"):
            reader = pypdf.PdfReader(path)
            return "\n".join(page.extract_text() or "" for page in reader.pages)
        elif path.endswith(".xlsx"):
            wb = openpyxl.load_workbook(path, data_only=True)
            t = ""
            for s in wb.sheetnames:
                ws = wb[s]
                for r in ws.iter_rows(values_only=True):
                    if any(v is not None for v in r):
                        t += "\n" + " | ".join(str(v) if v is not None else "" for v in r)
            return t
        elif path.endswith((".eml", ".txt", ".csv", ".md", ".json")):
            with open(path, errors="ignore") as f:
                return f.read()
    except Exception as e:
        return f"ERROR: {e}"
    return ""

keywords = ["corwyn", "0629", "brantley", "wrenford", "acht", "halbrook", "rennick", "osei", "ferreira", "aln-072", "corvane", "ravenell", "ardenne", "vx-140c"]
for root, dirs, files in os.walk("/filesystem"):
    for fn in files:
        p = os.path.join(root, fn)
        txt = get_all_text(p).lower()
        matched = [k for k in keywords if k in txt]
        if matched:
            print(f"{p}: {matched}")
'

