import openpyxl, pypdf

def text_xlsx(path):
    wb = openpyxl.load_workbook(path, data_only=True)
    out = [f"=== XLSX: {path} ==="]
    for name in wb.sheetnames:
        out.append(f"--- Sheet: {name} ---")
        ws = wb[name]
        for row in ws.iter_rows(values_only=True):
            if any(v is not None for v in row):
                out.append(" | ".join(str(v) if v is not None else "" for v in row))
    return "\n".join(out)

def text_pdf(path):
    reader = pypdf.PdfReader(path)
    out = [f"=== PDF: {path} ==="]
    for i, page in enumerate(reader.pages):
        out.append(f"--- Page {i+1} ---")
        out.append(page.extract_text())
    return "\n".join(out)

files = [
    "/filesystem/Equipment/PXA-2023-0629_Corwyn_Canopy_String_and_Combiner_Schedule.xlsx",
    "/filesystem/Equipment/PXA-2023-0629_Corwyn_Canopy_Cable_Schedule.xlsx",
    "/filesystem/Equipment/PXA-2023-0629_Corwyn_Monitoring_and_Communications_Schedule.xlsx",
    "/filesystem/Equipment/Vexlar_VX-C_Series_Inverter_Data_Sheet.pdf",
    "/filesystem/Equipment/Ravenell_RCB-12-1000_Combiner_Data_Sheet.pdf",
]
with open("/tmp/corwyn_3_mid.txt", "w") as fw:
