        print(p.text)
for t in doc.tables:
    for r in t.rows:
        print([c.text.strip() for c in r.cells])
"

python3 -c "
import openpyxl
for f in ['/filesystem/Equipment/PXA-2023-0629_Corwyn_Equipment_Schedule.xlsx', '/filesystem/Equipment/PXA-2023-0629_Corwyn_Canopy_Cable_Schedule.xlsx']:
    wb = openpyxl.load_workbook(f, data_only=True)
    for s in wb.sheetnames:
        if s not in ['Header', 'Inverter Output Circuits']:
            print('===', f, s)
            for r in wb[s].iter_rows(values_only=True):
                if any(r):
                    print([str(c) if c is not None else '' for c in r])
"

python3 -c "
import os, openpyxl, docx, pypdf

for root, dirs, files in os.walk('/filesystem'):
    for fn in files:
        p = os.path.join(root, fn)
        if fn == 'Corwyn_PTO_Memo.docx':
            continue
        try:
            if fn.endswith('.xlsx'):
                wb = openpyxl.load_workbook(p, data_only=True)
                for s in wb.sheetnames:
                    for r in wb[s].iter_rows(values_only=True):
                        row_str = ' '.join(str(c) for c in r if c is not None)
                        if 'corwyn' in row_str.lower() or '0629' in row_str.lower() or 'vx-140c' in row_str.lower():
                            print(f'XLSX {p} [{s}]: {row_str[:200]}')
            elif fn.endswith('.docx'):
                d = docx.Document(p)
                for para in d.paragraphs:
                    if 'corwyn' in para.text.lower() or '0629' in para.text.lower():
                        print(f'DOCX {p}: {para.text[:200]}')
            elif fn.endswith('.pdf'):
                r = pypdf.PdfReader(p)
                for idx, page in enumerate(r.pages):
                    t = page.extract_text() or ''
                    if 'corwyn' in t.lower() or '0629' in t.lower():
                        print(f'PDF {p} [p.{idx+1}] matches')
            elif fn.endswith('.eml'):
                with open(p) as f:
                    t = f.read()
                if 'corwyn' in t.lower() or '0629' in t.lower():
                    print(f'EML {p} matches')
        except Exception as e:
            print(f'ERR {p}: {e}')
"

